def countPalindromicPaths(matrix):
    n = len(matrix)
    m = len(matrix[0])
    MOD = 10**9 + 7

    # Helper function to check if a string is a palindrome
    def is_palindrome(s):
        return s == s[::-1]

    # Initialize dp array
    dp = [[0] * m for _ in range(n)]
    dp[0][0] = 1

    # Precompute the number of palindromic paths ending at each cell
    for i in range(n):
        for j in range(m):
            if i > 0:
                dp[i][j] += dp[i-1][j]
            if j > 0:
                dp[i][j] += dp[i][j-1]
            if i > 0 and j > 0:
                if matrix[i][j] == matrix[i-1][j-1]:
                    dp[i][j] += dp[i-1][j-1]
            dp[i][j] %= MOD

    return dp[n-1][m-1]

